SELECT cc_id FROM componentes_composicao WHERE cc_comp_id = (SELECT comp_id FROM composicao WHERE comp_procod = (SELECT codigo_vf FROM migracao_multiloja.vinculo WHERE loj_codigo = {{loja_destino}} AND tipo = 'produto' AND codigo_origem = %(procod)s::text) ORDER BY comp_id LIMIT 1) AND cc_procod = (SELECT codigo_vf FROM migracao_multiloja.vinculo WHERE loj_codigo = {{loja_destino}} AND tipo = 'produto' AND codigo_origem = %(cc_procod)s::text)
